corrected_code:
const express = require('express');
const { UserProfile, DepartmentBadge } = require('../models');
const { checkAuth } = require('../auth');

const app = express();

UserProfile.addHook('afterFind', async (profile) => {
  if (profile) {
    const badges = await DepartmentBadge.findAll({ where: { departmentId: profile.departmentId } });
    profile.setDataValue('departmentBadges', badges);
  }
});

app.get('/api/directory/profiles/:profileId', checkAuth, async (req, res) => {
  // Ensure profile lookup is restricted to the user's organization
  const profile = await UserProfile.findOne({
    where: {
      id: req.params.profileId,
      organizationId: req.user.organizationId
    }
  });

  if (!profile) {
    return res.status(404).json({ error: 'Profile not found in your organization' });
  }

  res.json({ profile });
});

app.listen(8110);
